INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.101.0',
  '2026-09-23',
  'Оформление: образец темы, размер интерфейса и перенос настроек',
  E'В «Оформлении» появился образец: карточка с заголовком, текстом, кнопками и полем ввода — ровно теми цветами, что выбраны. Видно, что получилось, не разглядывая всю страницу.\n\nРядом с предупреждением о контрасте теперь есть кнопка «Починить контраст»: она подбирает читаемый цвет текста, сохраняя его оттенок, а фон оставляет как задумано.\n\n«Размер интерфейса» — три кнопки (компактный, обычный, крупный) и ползунок от 70 до 150 %. Меняются разом шрифт и отступы, как масштаб страницы в браузере. Настройка своя у Telegram и у браузера. Если браузер старый и масштаб менять не умеет, вместо ползунка написано об этом.\n\nНовый раздел «Перенос настроек»: тема, свои цвета, сохранённые темы, настройки фона, скрытые страницы и закреплённые заголовки копируются одной строкой или сохраняются файлом — и вставляются на другом устройстве или в другом аккаунте. Там же «Сбросить оформление»: всё возвращается к обычному, загруженные картинки остаются. Сами картинки не переносятся — файл принадлежит аккаунту; переезжают размещение, размытие и затемнение, а ссылка на картинку — если фон был задан ссылкой.',
  E'store.AppearanceState получил поле Scale (проценты, omitempty; проверка 70–150 или 0 в appearance.set). Применяется в themes.applyScale через CSS zoom на корне: размеры в приложении заданы в пикселях, и font-size на html подвинул бы только тексты без явного размера. Поддержка проверяется CSS.supports(''zoom'') — на Safari до 18 и старых Firefox ползунок скрыт с пояснением. apply() в appearance.ts зовёт applyScale, поэтому масштаб восстанавливается вместе с темой из кэша, до ответа сервера.\n\nthemes.fixContrast(text, bg, 4.5): оттенок и насыщенность сохраняем, двигаем светлоту шагами по 5 % в сторону от фона, пока contrastRatio не дотянет до порога; если не дотягивает вовсе — чистый белый или чёрный. Кнопка правит только токен text.\n\nTransferBlock.vue собирает {app, kind, version, state, themes, placement, background, hidden_pages, pinned_pages, pin_all_headers}; применение идёт по частям существующими ручками, пропущенное не трогается. Для фона ручка требует картинку целиком, поэтому эффекты накладываются на текущую: своя картинка остаётся на месте, ссылка из переноса заменяет. Добавлен экспорт setAppearanceState — обычные правки идут по кусочку через selectTheme/editToken, а здесь приходит готовое состояние. В settings/sections.ts новая секция id 7.\n\nПроверено в браузере: образец темы, «Починить контраст» на паре #121212/#2a2a2a (1,3:1 → 4,9:1), пресеты и ползунок масштаба (zoom 1.15, scale 115 в базе), полный круг переноса — копирование, сброс до значений по умолчанию и применение сохранённой строки обратно.'
);
